fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"

piece_vals = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0,
              'p':-100,'n':-320,'b':-330,'r':-500,'q':-900,'k':0}

def evaluate(fen):
    # terminal handled by caller
    parts = fen.split()
    board = parts[0]
    turn = parts[1]
    score = 0
    rank = 8
    for row in board.split('/'):
        file = 0
        for ch in row:
            if ch.isdigit():
                file += int(ch)
                continue
            sq = "abcdefgh"[file] + str(rank)
            score += piece_vals.get(ch,0)
            if sq in ('d4','e4','d5','e5'):
                score += 12 if ch.isupper() else -12
            file += 1
        rank -= 1
    # check term
    # need in_check from simulate; caller handles
    return score

def is_terminal(state):
    return state.get('game_over')

def score_state(state):
    if state.get('game_over'):
        w = state.get('winner')
        if w == 'white': return 100000
        if w == 'black': return -100000
        return 0
    s = evaluate(state['fen'])
    if state.get('in_check'):
        if state['turn'] == 'black':
            s += 25
        else:
            s -= 25
    return s

start = simulate_move(fen, None)
cands = sorted(start['legal_moves'])
best = None
best_score = -10**9
results = []
for c in cands:
    aw = simulate_move(fen, c)
    if aw.get('game_over'):
        sc = score_state(aw)
        results.append((c, sc, 'terminal'))
    else:
        replies = aw['legal_moves']
        worst = 10**9
        for r in replies:
            af = simulate_move(aw['fen'], r)
            sc = score_state(af)
            if sc < worst:
                worst = sc
        sc = worst
        results.append((c, sc, len(replies)))
    if sc > best_score:
        best_score = sc
        best = c

for r in results:
    print(r)
print("BEST", best, best_score)
play_move(best)
